// Generated by pac publish experiments. Do not edit; the next run overwrites it.
//
// The tag filter of the overview of the catalog (step Ft5Miju6). Without JavaScript,
// the overview is a plain list of all experiments. With it, this script reads
// `assets/experiments.json` (the tags of each experiment, by group) and builds a panel
// of the tags: a column to the right of the list on a wide screen, a closed block
// "Filter" above the list on a phone. A tap moves a tag through three states:
// neutral (no effect), "+" (the experiment must have the tag), and "−" (the experiment
// must not have it). The list shows each experiment with all "+" tags and no "−" tag.
// The address keeps the state, for example `#f=+physics,-m_candle`, so a person can
// share a filtered list.
//
// The pure functions are in `api`; node tests them by `require` with no DOM.
"use strict";

(function () {
  const DATA_VERSION = 1;
  const NEUTRAL = "";
  const PROMOTE = "+";
  const INHIBIT = "-";
  const HASH_KEY = "f";

  // neutral -> "+" -> "-" -> neutral
  function nextState(state) {
    if (state === PROMOTE) return INHIBIT;
    if (state === INHIBIT) return NEUTRAL;
    return PROMOTE;
  }

  // True if the tags (an array of refs) hold each "+" tag and no "-" tag of the filter.
  function matches(tags, filter) {
    const have = new Set(tags);
    for (const ref of Object.keys(filter)) {
      if (filter[ref] === PROMOTE && !have.has(ref)) return false;
      if (filter[ref] === INHIBIT && have.has(ref)) return false;
    }
    return true;
  }

  // The names of the experiments that the filter shows, in their order.
  function shown(experiments, filter) {
    return experiments.filter((item) => matches(item.tags, filter)).map((item) => item.name);
  }

  // The number of experiments of each tag ref.
  function counts(experiments) {
    const result = {};
    for (const item of experiments) {
      for (const ref of new Set(item.tags)) result[ref] = (result[ref] || 0) + 1;
    }
    return result;
  }

  // The filter of an address hash such as "#f=+physics,-m_candle". A ref that is not in
  // `known` (if given) and a token without a sign are left out; the last token of a ref wins.
  function parseHash(hash, known) {
    const filter = {};
    const allowed = known ? new Set(known) : null;
    const text = (hash || "").replace(/^#/, "");
    for (const part of text.split("&")) {
      if (!part.startsWith(HASH_KEY + "=")) continue;
      let value = part.slice(HASH_KEY.length + 1);
      try {
        value = decodeURIComponent(value);
      } catch (error) {
        continue;
      }
      for (const token of value.split(",")) {
        const sign = token.charAt(0);
        const ref = token.slice(1);
        if ((sign !== PROMOTE && sign !== INHIBIT) || !ref) continue;
        if (allowed && !allowed.has(ref)) continue;
        filter[ref] = sign;
      }
    }
    return filter;
  }

  // The hash of a filter without "#", for example "f=+physics,-m_candle", or "" for no
  // filter. The tokens follow `order` (the refs of the panel), else the keys of the filter.
  function formatHash(filter, order) {
    const refs = order || Object.keys(filter);
    const tokens = [];
    for (const ref of refs) {
      const state = filter[ref];
      if (state === PROMOTE || state === INHIBIT) tokens.push(state + ref);
    }
    return tokens.length ? HASH_KEY + "=" + tokens.join(",") : "";
  }

  const api = { DATA_VERSION, nextState, matches, shown, counts, parseHash, formatHash };

  // The page

  const STATE_TEXT = {
    [NEUTRAL]: "",
    [PROMOTE]: "muss dabei sein",
    [INHIBIT]: "darf nicht dabei sein",
  };
  const SIGN = { [NEUTRAL]: "", [PROMOTE]: "+", [INHIBIT]: "−" };
  const WIDE = "(min-width: 1000px)";

  function element(tag, attributes, text) {
    const node = document.createElement(tag);
    for (const name of Object.keys(attributes || {})) node.setAttribute(name, attributes[name]);
    if (text !== undefined) node.textContent = text;
    return node;
  }

  // The page name of a link, for example "mi-402" of "/catalog/experiments/mi-402.html".
  function pageName(href) {
    const match = /experiments\/([^/?#]+?)(?:\.html|\.md)?(?:[?#].*)?$/.exec(href || "");
    return match ? decodeURIComponent(match[1]) : null;
  }

  function findList() {
    for (const list of document.querySelectorAll("section ul")) {
      if (list.querySelector('li a[href*="experiments/"]')) return list;
    }
    return null;
  }

  function build(data, list) {
    const items = {};
    for (const li of list.children) {
      const link = li.querySelector('a[href*="experiments/"]');
      const name = link && pageName(link.getAttribute("href"));
      if (name) items[name] = li;
    }
    const experiments = data.experiments.filter((item) => items[item.name]);
    const number = counts(experiments);
    const order = [];
    const buttons = {};
    let filter = {};

    const layout = element("div", { class: "filter-layout" });
    const aside = element("aside", { class: "filter", "aria-label": "Filter nach Tags" });
    const status = element("p", { class: "filter-status", "aria-live": "polite" });
    const count = element("span", { class: "filter-count" });
    const reset = element("button", { type: "button", class: "filter-reset" }, "Zurücksetzen");
    status.append(count, " ", reset);
    const details = element("details", { class: "filter-box" });
    const summary = element("summary", {}, "Filter");
    details.append(summary);
    const help = element(
      "p",
      { class: "filter-help" },
      "Tippen: + muss dabei sein, nochmal: − darf nicht dabei sein, nochmal: egal."
    );
    details.append(help);

    for (const group of data.groups) {
      const tags = group.tags.filter((tag) => number[tag.ref]);
      if (!tags.length) continue;
      const box = element("div", { class: "filter-group filter-group-" + group.group });
      box.append(element("h3", {}, group.label));
      const row = element("div", { class: "filter-tags" });
      for (const tag of tags) {
        order.push(tag.ref);
        const button = element("button", {
          type: "button",
          class: "ftag tag tag-" + group.group,
          "data-ref": tag.ref,
          "data-state": "neutral",
        });
        button.append(
          element("span", { class: "ftag-sign", "aria-hidden": "true" }),
          element("span", { class: "ftag-label" }, tag.label),
          element("span", { class: "ftag-count" }, String(number[tag.ref]))
        );
        button.dataset.label = tag.label;
        button.addEventListener("click", () => {
          const state = nextState(filter[tag.ref] || NEUTRAL);
          if (state === NEUTRAL) delete filter[tag.ref];
          else filter[tag.ref] = state;
          apply(true);
        });
        buttons[tag.ref] = button;
        row.append(button);
      }
      box.append(row);
      details.append(box);
    }
    if (!order.length) return;
    aside.append(status, details);

    reset.addEventListener("click", () => {
      filter = {};
      apply(true);
    });

    function apply(write) {
      const visible = new Set(shown(experiments, filter));
      for (const name of Object.keys(items)) items[name].hidden = !visible.has(name);
      for (const ref of order) {
        const state = filter[ref] || NEUTRAL;
        const button = buttons[ref];
        button.dataset.state = state === PROMOTE ? "promote" : state === INHIBIT ? "inhibit" : "neutral";
        button.querySelector(".ftag-sign").textContent = SIGN[state];
        const label = button.dataset.label + " (" + number[ref] + ")";
        button.setAttribute("aria-label", STATE_TEXT[state] ? label + ": " + STATE_TEXT[state] : label);
        button.setAttribute("aria-pressed", state === NEUTRAL ? "false" : "true");
      }
      const active = Object.keys(filter).length;
      count.textContent = visible.size + " von " + experiments.length + " Experimenten";
      reset.disabled = active === 0;
      summary.textContent = active ? "Filter (" + active + " aktiv)" : "Filter";
      empty.hidden = visible.size > 0;
      if (write) {
        const hash = formatHash(filter, order);
        const address = location.pathname + location.search + (hash ? "#" + hash : "");
        history.replaceState(null, "", address);
      }
    }

    const empty = element("p", { class: "filter-empty" }, "Kein Experiment passt zu diesem Filter.");
    list.parentNode.insertBefore(layout, list);
    const column = element("div", { class: "filter-list" });
    column.append(list, empty);
    layout.append(aside, column);
    document.body.classList.add("has-filter");

    const wide = window.matchMedia ? window.matchMedia(WIDE) : null;
    function fit() {
      if (wide && wide.matches) details.open = true;
    }
    if (wide) {
      fit();
      if (wide.addEventListener) wide.addEventListener("change", fit);
    }

    filter = parseHash(location.hash, order);
    if (Object.keys(filter).length && !(wide && wide.matches)) details.open = true;
    apply(false);
    window.addEventListener("hashchange", () => {
      filter = parseHash(location.hash, order);
      apply(false);
    });
  }

  function init() {
    const script = document.querySelector("script[data-filter-data]");
    const list = findList();
    if (!script || !list || !window.fetch) return;
    fetch(script.getAttribute("data-filter-data"))
      .then((response) => (response.ok ? response.json() : null))
      .then((data) => {
        if (data && data.version === DATA_VERSION && Array.isArray(data.groups)) build(data, list);
      })
      .catch(() => {});
  }

  if (typeof module !== "undefined" && module.exports) module.exports = api;
  if (typeof window !== "undefined" && typeof document !== "undefined") {
    window.pacCatalogFilter = api;
    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
    else init();
  }
})();
